import re
from typing import List


class TableSanitizer:
    """Sanitizes markdown tables generated by document parsing models (e.g. TableFormer)."""

    @staticmethod
    def _is_table_row(line: str) -> bool:
        stripped = line.strip()
        return stripped.startswith("|") and stripped.endswith("|") and len(stripped) > 1

    @staticmethod
    def _is_separator_row(line: str) -> bool:
        stripped = line.strip()
        if not (stripped.startswith("|") and stripped.endswith("|")):
            return False
        cells = [c.strip() for c in stripped.strip("|").split("|")]
        return all(re.fullmatch(r":?-+:?", cell) for cell in cells if cell)

    @staticmethod
    def _is_empty_row(cells: List[str]) -> bool:
        return all(cell == "" for cell in cells)

    def clean(self, markdown_text: str) -> str:
        """Cleans and sanitizes tables in markdown text."""
        lines = markdown_text.splitlines()
        cleaned_lines: List[str] = []
        in_table = False
        seen_separator_in_current_table = False

        for line in lines:
            stripped = line.strip()

            if self._is_table_row(line):
                cells = [c.strip() for c in stripped.strip("|").split("|")]

                if self._is_separator_row(line):
                    if not in_table:
                        # Stray separator, skip
                        continue
                    if seen_separator_in_current_table:
                        # Duplicate separator inside table body from page split, skip
                        continue
                    seen_separator_in_current_table = True
                    normalized_sep = "| " + " | ".join(cells) + " |"
                    cleaned_lines.append(normalized_sep)
                    continue

                if self._is_empty_row(cells):
                    # Drop empty layout artifact rows
                    continue

                in_table = True
                normalized_row = "| " + " | ".join(cells) + " |"
                cleaned_lines.append(normalized_row)
            else:
                in_table = False
                seen_separator_in_current_table = False
                cleaned_lines.append(line)

        return "\n".join(cleaned_lines)
